1	import { users } from '@/lib/schema';
2	import { type SQL, eq } from 'drizzle-orm';
3	import { PgDialect } from 'drizzle-orm/pg-core';
4	import { liveAnd, notDeleted } from '../soft-delete';
5	
6	const dialect = new PgDialect();
7	const render = (q: SQL): string => dialect.sqlToQuery(q).sql.toLowerCase();
8	
9	describe('soft-delete read helper', () => {
10	  it('notDeleted renders `deleted_at IS NULL`', () => {
11	    expect(render(notDeleted(users.deletedAt))).toContain(
12	      '"deleted_at" is null',
13	    );
14	  });
15	
16	  it('liveAnd composes notDeleted with extra predicates', () => {
17	    const sql = liveAnd(users.deletedAt, eq(users.flightSchoolId, 'org-1'));
18	    expect(sql).toBeDefined();
19	    const rendered = render(sql as SQL);
20	    expect(rendered).toContain('"deleted_at" is null');
21	    expect(rendered).toContain(' and ');
22	    expect(rendered).toContain('"flight_school_id"');
23	  });
24	
25	  it('liveAnd ignores undefined predicates', () => {
26	    const sql = liveAnd(users.deletedAt, undefined);
27	    expect(render(sql as SQL)).toContain('"deleted_at" is null');
28	  });
29	});
